"use client"
import * as React from "react"
import { RotateCw, X } from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Attachment,
  AttachmentGroup,
  AttachmentMedia,
  AttachmentContent,
  AttachmentTitle,
  AttachmentDescription,
  AttachmentActions,
  AttachmentAction,
} from "@/components/ui/attachment"
import { useControllableState } from "@/hooks/use-controllable-state"
import { FileUploadPreview } from "./file-upload-parts"
import type { FileUploadProps } from "./types"
import { useFileSelection, useFileUploadReset } from "./use-file-selection"
import { describeAccept, formatFileSize, interpolate } from "./utils"

function FileUpload({
  value: prop,
  defaultValue = [],
  onValueChange,
  accept,
  maxSize = Infinity,
  maxFiles = Infinity,
  multiple = true,
  capture = "environment",
  disabled,
  error,
  labels: overrides,
  onReject,
  onRetry,
  className,
  "aria-describedby": describedBy,
  ...props
}: FileUploadProps) {
  const [items, setItems] = useControllableState({
    prop,
    defaultProp: defaultValue,
    onChange: onValueChange,
  })
  const selection = useFileSelection({
    accept,
    maxSize,
    maxFiles,
    multiple,
    labels: overrides,
    onReject,
  })
  const { labels, input, camera, message } = selection
  const [dragging, setDragging] = React.useState(false)
  const depth = React.useRef(0)
  useFileUploadReset(input, () => {
    if (prop === undefined) setItems(defaultValue)
    selection.clear()
  })
  const errorId = React.useId()
  const hintId = React.useId()
  // 被拒文件只在下方出一行说明，不把整个控件标成出错；出错态只跟随外部 error
  const invalid = Boolean(error || props["aria-invalid"])
  function add(files: File[]) {
    if (disabled) return
    const next = selection.select(files, items.length)
    if (next.length) setItems([...items, ...next])
  }
  function change(event: React.ChangeEvent<HTMLInputElement>) {
    add(Array.from(event.target.files ?? []))
    event.target.value = ""
  }
  const canCapture =
    capture !== false &&
    (!accept ||
      accept
        .split(",")
        .some((v) => /image\/|\.(jpe?g|png|webp|heic|heif|avif)/i.test(v)))
  return (
    <div
      data-slot="file-upload"
      data-disabled={disabled || undefined}
      className={cn("@container flex min-w-0 flex-col gap-3", className)}
      {...props}
    >
      <input
        data-slot="file-upload-input"
        ref={input}
        type="file"
        className="hidden"
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        onChange={change}
      />
      <input
        data-slot="file-upload-camera"
        ref={camera}
        type="file"
        className="hidden"
        accept="image/*"
        capture={capture || undefined}
        disabled={disabled}
        onChange={change}
      />
      <div
        data-slot="file-upload-dropzone"
        data-dragging={dragging || undefined}
        aria-invalid={invalid || undefined}
        aria-describedby={[
          describedBy,
          hintId,
          invalid || message ? errorId : null,
        ]
          .filter(Boolean)
          .join(" ")}
        className="flex flex-col items-center gap-3 rounded-xl border border-dashed border-edge bg-muted/40 p-5 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 data-[dragging]:border-solid data-[dragging]:bg-background dark:aria-invalid:ring-destructive/40"
        onDragEnter={(event) => {
          event.preventDefault()
          if (!disabled) {
            depth.current++
            setDragging(true)
          }
        }}
        onDragOver={(event) => event.preventDefault()}
        onDragLeave={() => {
          depth.current--
          if (depth.current <= 0) setDragging(false)
        }}
        onDrop={(event) => {
          event.preventDefault()
          depth.current = 0
          setDragging(false)
          add(Array.from(event.dataTransfer.files))
        }}
      >
        <div className="flex flex-wrap items-center justify-center gap-2 pointer-coarse:hidden">
          <span className="text-sm text-muted-foreground">{labels.drop}</span>
          <Button
            type="button"
            size="sm"
            variant="outline"
            disabled={disabled}
            aria-invalid={invalid || undefined}
            aria-describedby={invalid || message ? errorId : undefined}
            onClick={() => input.current?.click()}
          >
            {labels.choose}
          </Button>
        </div>
        <div className="hidden w-full gap-2 pointer-coarse:flex">
          {canCapture && (
            <Button
              type="button"
              size="lg"
              variant="outline"
              className="min-w-0 flex-1"
              disabled={disabled}
              onClick={() => camera.current?.click()}
            >
              {labels.camera}
            </Button>
          )}
          <Button
            type="button"
            size="lg"
            variant="outline"
            className="min-w-0 flex-1"
            disabled={disabled}
            onClick={() => input.current?.click()}
          >
            {labels.album}
          </Button>
        </div>
        <p id={hintId} className="text-center text-xs text-muted-foreground">
          {interpolate(labels.hint, {
            accept: accept ? describeAccept(accept) : labels.any,
            size: Number.isFinite(maxSize)
              ? formatFileSize(maxSize)
              : labels.unlimited,
          })}
        </p>
      </div>
      {items.length > 0 && (
        <AttachmentGroup className="flex-col overflow-visible">
          {items.map((item) => (
            <Attachment
              key={item.id}
              state={
                !item.status || item.status === "pending" ? "idle" : item.status
              }
              className="w-full flex-nowrap focus-within:ring-0"
            >
              <AttachmentMedia variant="image">
                <FileUploadPreview file={item.file} />
              </AttachmentMedia>
              <AttachmentContent>
                <AttachmentTitle title={item.file.name}>
                  {item.file.name}
                </AttachmentTitle>
                <AttachmentDescription className="font-mono">
                  {formatFileSize(item.file.size)}
                </AttachmentDescription>
                {item.status === "uploading" && item.progress !== undefined && (
                  <div
                    data-slot="file-upload-progress"
                    aria-hidden="true"
                    className="mt-1 h-1 overflow-hidden rounded-full bg-muted"
                  >
                    <div
                      className="h-full rounded-full bg-primary transition-[width] duration-200 motion-reduce:transition-none"
                      style={{
                        width: `${Math.max(0, Math.min(100, item.progress))}%`,
                      }}
                    />
                  </div>
                )}
                {item.error && (
                  <p className="text-xs text-destructive">{item.error}</p>
                )}
              </AttachmentContent>
              <AttachmentActions>
                <span className="text-xs text-muted-foreground">
                  {labels[item.status ?? "pending"]}
                  {item.status === "uploading" && item.progress !== undefined
                    ? ` ${Math.round(Math.max(0, Math.min(100, item.progress)))}%`
                    : ""}
                </span>
                {item.status === "error" && onRetry && (
                  <AttachmentAction
                    type="button"
                    size="icon-sm"
                    disabled={disabled}
                    aria-label={interpolate(labels.retry, {
                      name: item.file.name,
                    })}
                    onClick={() => onRetry(item)}
                  >
                    <RotateCw aria-hidden="true" />
                  </AttachmentAction>
                )}
                <AttachmentAction
                  type="button"
                  size="icon-sm"
                  disabled={disabled}
                  aria-label={interpolate(labels.remove, {
                    name: item.file.name,
                  })}
                  onClick={() => {
                    setItems(items.filter((v) => v.id !== item.id))
                    selection.clear()
                  }}
                >
                  <X aria-hidden="true" />
                </AttachmentAction>
              </AttachmentActions>
            </Attachment>
          ))}
        </AttachmentGroup>
      )}
      <div
        data-slot="file-upload-error"
        id={errorId}
        aria-live="polite"
        className="text-xs text-destructive"
      >
        {error || message}
      </div>
    </div>
  )
}
export { FileUpload }
export { FileUploadSlot } from "./file-upload-slot"
export {
  IdCardFrontIllustration,
  IdCardBackIllustration,
} from "./file-upload-parts"
export { appendFiles } from "./utils"
export type {
  FileUploadItem,
  FileUploadProps,
  FileUploadSlotProps,
  FileUploadRejection,
} from "./types"
export type { FileUploadLabels } from "./config"

"use client"
import * as React from "react"
import { cn } from "@/lib/utils"

function FileUploadPreview({
  file,
  className,
}: {
  file: File
  className?: string
}) {
  const image = React.useRef<HTMLImageElement>(null)
  const [failed, setFailed] = React.useState<File | null>(null)
  React.useEffect(() => {
    if (!file.type.startsWith("image/") || !image.current) return
    const url = URL.createObjectURL(file)
    image.current.src = url
    return () => URL.revokeObjectURL(url)
  }, [file])
  return (
    <span
      data-slot="file-upload-preview"
      className={cn(
        "flex size-full items-center justify-center overflow-hidden text-xs text-muted-foreground",
        className,
      )}
    >
      {file.type.startsWith("image/") && failed !== file ? (
        // objectURL 在 effect 中赋给原生图片，避免渲染期分配资源。
        // eslint-disable-next-line @next/next/no-img-element
        <img
          ref={image}
          alt=""
          className="size-full object-cover"
          onError={() => setFailed(file)}
        />
      ) : (
        <span className="font-mono uppercase">
          {file.name.split(".").pop()?.slice(0, 6)}
        </span>
      )}
    </span>
  )
}
function IdCardFrontIllustration(props: React.ComponentProps<"svg">) {
  return (
    <svg
      data-slot="id-card-front-illustration"
      viewBox="0 0 158 100"
      fill="none"
      stroke="currentColor"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="150" height="92" rx="8" />
      <circle cx="116" cy="37" r="12" />
      <path d="M96 74v-8a20 20 0 0 1 40 0v8M22 29h49M22 45h40M22 61h49M22 79h63" />
    </svg>
  )
}
function IdCardBackIllustration(props: React.ComponentProps<"svg">) {
  return (
    <svg
      data-slot="id-card-back-illustration"
      viewBox="0 0 158 100"
      fill="none"
      stroke="currentColor"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="150" height="92" rx="8" />
      <circle cx="79" cy="32" r="15" />
      <circle cx="79" cy="32" r="8" />
      <path d="M35 65h88M49 80h60" />
    </svg>
  )
}
export { FileUploadPreview, IdCardFrontIllustration, IdCardBackIllustration }

"use client"
import * as React from "react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { useControllableState } from "@/hooks/use-controllable-state"
import { FileUploadPreview, IdCardFrontIllustration } from "./file-upload-parts"
import { useFileSelection, useFileUploadReset } from "./use-file-selection"
import { interpolate } from "./utils"
import type { FileUploadSlotProps } from "./types"
function FileUploadSlot({
  label,
  placeholder,
  value: prop,
  defaultValue = null,
  onValueChange,
  accept = "image/*",
  maxSize = Infinity,
  capture = "environment",
  error,
  disabled,
  labels: overrides,
  onReject,
  className,
  ...props
}: FileUploadSlotProps) {
  const [item, setItem] = useControllableState({
    prop,
    defaultProp: defaultValue,
    onChange: onValueChange,
  })
  const { input, labels, message, clear, select } = useFileSelection({
    accept,
    maxSize,
    multiple: false,
    labels: overrides,
    onReject,
  })
  useFileUploadReset(input, () => {
    if (prop === undefined) setItem(defaultValue)
    clear()
  })
  const errorId = React.useId()
  // 被拒文件只在下方出一行说明，不把整个控件标成出错；出错态只跟随外部 error
  const invalid = Boolean(error || props["aria-invalid"])
  return (
    <div
      data-slot="file-upload-slot"
      className={cn("@container min-w-0", className)}
      {...props}
    >
      <p className="mb-2 text-sm font-medium">{label}</p>
      <input
        data-slot="file-upload-slot-input"
        ref={input}
        type="file"
        className="hidden"
        accept={accept}
        capture={capture || undefined}
        disabled={disabled}
        onChange={(event) => {
          const next = select(Array.from(event.target.files ?? []), 0)
          if (next[0]) setItem(next[0])
          event.target.value = ""
        }}
      />
      <div
        data-slot="file-upload-slot-control"
        aria-invalid={invalid || undefined}
        className={cn(
          "relative aspect-[1.58] rounded-xl border border-edge bg-muted/40 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40",
          !item && "border-dashed",
        )}
      >
        {item ? (
          <>
            <FileUploadPreview file={item.file} className="rounded-xl" />
            <div className="absolute right-2 bottom-2 flex gap-2">
              <Button
                type="button"
                size="sm"
                variant="outline"
                disabled={disabled}
                onClick={() => input.current?.click()}
              >
                {labels.replace}
              </Button>
              <Button
                type="button"
                size="sm"
                variant="outline"
                disabled={disabled}
                aria-label={interpolate(labels.remove, {
                  name: item.file.name,
                })}
                onClick={() => {
                  setItem(null)
                  clear()
                }}
              >
                {labels.delete}
              </Button>
            </div>
          </>
        ) : (
          <button
            data-slot="file-upload-slot-trigger"
            type="button"
            disabled={disabled}
            aria-describedby={invalid || message ? errorId : undefined}
            className="flex size-full flex-col items-center justify-center gap-3 rounded-xl text-sm outline-none focus-visible:ring-3 focus-visible:ring-ring/50 disabled:opacity-50"
            onClick={() => input.current?.click()}
          >
            {placeholder ?? (
              <IdCardFrontIllustration className="w-24 text-muted-foreground" />
            )}
            <span>{interpolate(labels.upload, { label })}</span>
          </button>
        )}
      </div>
      <div
        data-slot="file-upload-slot-error"
        id={errorId}
        aria-live="polite"
        className="mt-2 text-xs text-destructive"
      >
        {error || message}
      </div>
    </div>
  )
}
export { FileUploadSlot }

import type * as React from "react"
import type { FileUploadLabels } from "./config"
type FileUploadItem = {
  id: string
  file: File
  status?: "pending" | "uploading" | "error" | "done"
  progress?: number
  error?: string
}
type FileUploadRejection = { file: File; reason: "type" | "size" | "count" }
type FileUploadCommonProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange"
> & {
  /** MIME 或扩展名列表，逗号分隔。@default undefined */
  accept?: string
  /** 单文件大小上限，字节。@default Infinity */
  maxSize?: number
  /** 手机拍照方向；false 隐藏拍照。@default "environment" */
  capture?: "user" | "environment" | false
  /** 整体错误提示。 */
  error?: React.ReactNode
  /** @default false */
  disabled?: boolean
  labels?: Partial<FileUploadLabels>
  onReject?: (rejections: FileUploadRejection[]) => void
}
type FileUploadProps = FileUploadCommonProps & {
  value?: FileUploadItem[]
  /** @default [] */
  defaultValue?: FileUploadItem[]
  onValueChange?: (value: FileUploadItem[]) => void
  /** 总文件数上限。@default Infinity */
  maxFiles?: number
  /** @default true */
  multiple?: boolean
  /** 传入后，上传失败的条目右侧出现「重试」按钮；重新上传由使用方完成 */
  onRetry?: (item: FileUploadItem) => void
}
type FileUploadSlotProps = FileUploadCommonProps & {
  label: string
  placeholder?: React.ReactNode
  value?: FileUploadItem | null
  /** @default null */
  defaultValue?: FileUploadItem | null
  onValueChange?: (value: FileUploadItem | null) => void
}
export type {
  FileUploadItem,
  FileUploadRejection,
  FileUploadProps,
  FileUploadSlotProps,
}

"use client"
import * as React from "react"
import { DEFAULT_LABELS } from "./config"
import type { FileUploadProps } from "./types"
import {
  describeAccept,
  formatFileSize,
  interpolate,
  validateFiles,
} from "./utils"
function useFileSelection({
  accept,
  maxSize = Infinity,
  maxFiles = Infinity,
  multiple = true,
  labels: overrides,
  onReject,
}: FileUploadProps) {
  const labels = { ...DEFAULT_LABELS, ...overrides }
  const [message, setMessage] = React.useState("")
  const input = React.useRef<HTMLInputElement>(null)
  const camera = React.useRef<HTMLInputElement>(null)
  function select(files: File[], count: number) {
    const result = validateFiles(
      files,
      accept,
      maxSize,
      Math.max(0, Math.min(maxFiles, multiple ? Infinity : 1) - count),
    )
    setMessage(
      result.rejected
        .map(({ file, reason }) =>
          interpolate(
            reason === "type"
              ? labels.typeError
              : reason === "size"
                ? labels.sizeError
                : labels.countError,
            {
              name: file.name,
              accept: accept ? describeAccept(accept) : labels.any,
              size: formatFileSize(maxSize),
              count: multiple ? maxFiles : 1,
            },
          ),
        )
        .filter((v, i, all) => all.indexOf(v) === i)
        .join("；"),
    )
    if (result.rejected.length) onReject?.(result.rejected)
    return result.accepted
  }
  return { labels, message, clear: () => setMessage(""), input, camera, select }
}
function useFileUploadReset(
  input: React.RefObject<HTMLInputElement | null>,
  onReset: () => void,
) {
  const callback = React.useEffectEvent(onReset)
  React.useEffect(() => {
    const form = input.current?.form
    function reset(event: Event) {
      queueMicrotask(() => {
        if (!event.defaultPrevented) callback()
      })
    }
    form?.addEventListener("reset", reset)
    return () => form?.removeEventListener("reset", reset)
  }, [input])
}
export { useFileSelection, useFileUploadReset }

import type { FileUploadItem, FileUploadRejection } from "./types"
function formatFileSize(size: number) {
  const unit = size >= 1048576 ? "MB" : size >= 1024 ? "KB" : "B"
  return `${new Intl.NumberFormat("zh-CN", { maximumFractionDigits: 1 }).format(size / (unit === "MB" ? 1048576 : unit === "KB" ? 1024 : 1))} ${unit}`
}
function acceptsFile(file: File, accept?: string) {
  return (
    !accept?.trim() ||
    accept.split(",").some((part) => {
      const rule = part.trim().toLowerCase()
      if (!rule) return false
      if (rule.startsWith(".")) return file.name.toLowerCase().endsWith(rule)
      return rule.endsWith("/*")
        ? file.type.toLowerCase().startsWith(rule.slice(0, -1))
        : file.type.toLowerCase() === rule
    })
  )
}
function validateFiles(
  files: File[],
  accept: string | undefined,
  maxSize: number,
  available: number,
) {
  const accepted: FileUploadItem[] = []
  const rejected: FileUploadRejection[] = []
  for (const file of files) {
    const reason = !acceptsFile(file, accept)
      ? "type"
      : file.size > maxSize
        ? "size"
        : accepted.length >= available
          ? "count"
          : null
    if (reason) rejected.push({ file, reason })
    else accepted.push({ id: createId(), file, status: "pending" })
  }
  return { accepted, rejected }
}
let seed = 0
/** 局域网 http 页面（非安全上下文）没有 crypto.randomUUID，用自增序号兜底 */
function createId() {
  return typeof crypto !== "undefined" && "randomUUID" in crypto
    ? crypto.randomUUID()
    : `file-${Date.now().toString(36)}-${++seed}`
}

const MIME_NAMES: Record<string, string> = {
  "image/*": "图片",
  "video/*": "视频",
  "audio/*": "音频",
  "application/pdf": "PDF",
}

/** 把 accept 转成给人看的格式说明：`image/*,.pdf` → 「图片、PDF」 */
function describeAccept(accept: string) {
  const names = accept
    .split(",")
    .map((part) => part.trim().toLowerCase())
    .filter(Boolean)
    .map(
      (rule) =>
        MIME_NAMES[rule] ??
        (rule.startsWith(".")
          ? rule.slice(1).toUpperCase()
          : (rule.split("/")[1] ?? rule).toUpperCase()),
    )
  return [...new Set(names)].join("、")
}

/** 提交时显式追加文件，不修改原生 file input。 */
function appendFiles(
  formData: FormData,
  name: string,
  items: FileUploadItem[],
) {
  for (const item of items) formData.append(name, item.file, item.file.name)
}
function interpolate(
  template: string,
  values: Record<string, string | number>,
) {
  return template.replace(/\{(\w+)\}/g, (match, key: string) =>
    String(values[key] ?? match),
  )
}
export {
  appendFiles,
  acceptsFile,
  describeAccept,
  formatFileSize,
  validateFiles,
  interpolate,
}

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }
